EXTRA_PIXEL_DATA=''

def extra_pixels(index):
    record=EXTRA_PIXEL_ROWS[index];raw=zlib.decompress(base64.b64decode(EXTRA_PIXEL_DATA))
    selected=raw[record['offset']:record['offset']+record['bytes']]
    assert hashlib.sha256(selected).hexdigest()==record['rgb_sha256']
    return Image.frombytes('RGB',tuple(record['size']),selected),record['box']


def v21_navigation_fixture(index):
    strip,box=extra_pixels(index);image=Image.new('RGB',(720,1280),(42,42,42))
    image.paste(strip,tuple(box[:2]))
    metadata=copy.deepcopy(EXTRA_PIXEL_ROWS[index]['source_metadata'])
    rendered=io.BytesIO();image.save(rendered,format='PNG')
    metadata['screenshot_sha256']=hashlib.sha256(rendered.getvalue()).hexdigest()
    metadata['fixture_scope']='Exact original V21 navigation pixels; synthetic outside, host-model only'
    return image,metadata


